import React, { useState, useCallback } from 'react';
import { Calendar, ButtonGroup, Button, Stack } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
  initialDate?: Date;
}

const startOfDay = (date: Date): Date => {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
};

const addDays = (date: Date, days: number): Date => {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
};

const ReportDatePicker: React.FC<ReportDatePickerProps> = ({
  onChange,
  initialDate,
}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(
    startOfDay(initialDate ?? new Date())
  );

  const handleDateChange = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  const handleToday = useCallback(() => {
    handleDateChange(new Date());
  }, [handleDateChange]);

  const handleYesterday = useCallback(() => {
    handleDateChange(addDays(new Date(), -1));
  }, [handleDateChange]);

  const handleWeekAgo = useCallback(() => {
    handleDateChange(addDays(new Date(), -7));
  }, [handleDateChange]);

  return (
    <Stack direction="column" gap="var(--jx-space-3)" className="jx-report-date-picker">
      <ButtonGroup className="jx-report-date-picker__quick-options">
        <Button variant="secondary" size="sm" onClick={handleToday}>
          Сегодня
        </Button>
        <Button variant="secondary" size="sm" onClick={handleYesterday}>
          Вчера
        </Button>
        <Button variant="secondary" size="sm" onClick={handleWeekAgo}>
          Неделя назад
        </Button>
      </ButtonGroup>

      <Calendar
        value={selectedDate}
        onChange={handleDateChange}
        view="month"
        className="jx-report-date-picker__calendar"
      />
    </Stack>
  );
};

export default ReportDatePicker;

